import os
import time
from typing import Any, Dict, List, Optional

import assemblyai as aai


def _normalize_utterances(result: Any) -> List[Dict[str, Any]]:
    utterances = getattr(result, "utterances", None) or []
    normalized = []
    for u in utterances:
        normalized.append(
            {
                "speaker": getattr(u, "speaker", None),
                "start_ms": getattr(u, "start", None),
                "end_ms": getattr(u, "end", None),
                "text": getattr(u, "text", None),
            }
        )
    return normalized


def transcribe_meeting_with_diarization(
    audio_file: str,
    wait_poll_seconds: float = 5.0,
) -> Dict[str, Any]:
    api_key = os.environ.get("ASSEMBLYAI_API_KEY")
    if not api_key:
        raise EnvironmentError("ASSEMBLYAI_API_KEY is required")

    aai.settings.api_key = api_key

    config = aai.TranscriptionConfig(speaker_labels=True)
    transcript = aai.Transcriber().transcribe(audio_file, config)

    while transcript.status not in ("completed", "error", "failed"):
        time.sleep(wait_poll_seconds)
        transcript = aai.Transcript.get(transcript.id)

    if transcript.status != "completed":
        raise RuntimeError(f"Transcription failed: {getattr(transcript, 'error', 'unknown error')}")

    return {
        "id": transcript.id,
        "status": transcript.status,
        "text": transcript.text,
        "utterances": _normalize_utterances(transcript),
    }
